import { writable } from "svelte/store";

export interface CartLine {
    sku: string;
    quantity: number;
}

const stored = localStorage.getItem("cart");
// TODO: build the cart store, derive the item count, and load saved lines without touching browser APIs during a build
export const cart = writable<CartLine[]>(stored === null ? [] : JSON.parse(stored));

export function addLine(line: CartLine): void {
    cart.update(function append(lines) {
        lines.push(line);
        return lines;
    });
}
